"use client";

import { useState, useEffect } from "react";
import { Users, Filter, Search, RotateCcw, Plus } from "lucide-react";
import PersonaForm from "@/components/PersonaForm";
import PersonaCard from "@/components/PersonaCard";
import type { Persona, PersonaFormData } from "@/types";

export default function PersonasPage() {
  const [personas, setPersonas] = useState<Persona[]>([]);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [query, setQuery] = useState("");
  const [showForm, setShowForm] = useState(false);

  const fetchPersonas = async () => {
    try {
      setLoading(true);
      const res = await fetch(`/api/personas?q=${encodeURIComponent(query)}`);
      const data = await res.json();
      if (data.success) {
        setPersonas(data.data);
      }
    } catch (err) {
      console.error("Failed to fetch personas:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPersonas();
  }, []);

  const handleGenerate = async (formData: PersonaFormData) => {
    try {
      setGenerating(true);
      const res = await fetch("/api/personas/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      const data = await res.json();
      if (data.success) {
        setPersonas((prev) => [...data.data, ...prev]);
        setShowForm(false);
      }
    } catch (err) {
      console.error("Generation failed:", err);
    } finally {
      setGenerating(false);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const res = await fetch(`/api/personas?id=${id}`, { method: "DELETE" });
      const data = await res.json();
      if (data.success) {
        setPersonas((prev) => prev.filter((p) => p.id !== id));
      }
    } catch (err) {
      console.error("Delete failed:", err);
    }
  };

  return (
    <div className="min-h-full p-8 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex items-center justify-between mb-10">
        <div>
          <h1 className="font-display text-3xl font-bold mb-2">Persona Library</h1>
          <p className="text-sm" style={{ color: "var(--text-secondary)" }}>
            Manage and generate detailed user profiles for your research.
          </p>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-semibold transition-all"
          style={{
            background: "var(--amber-400)",
            color: "black",
            boxShadow: "0 4px 12px rgba(251, 191, 36, 0.2)",
          }}
        >
          {showForm ? "Cancel" : <><Plus size={16} /> New Persona</>}
        </button>
      </div>

      {/* Generation Form */}
      {showForm && (
        <div 
          className="mb-10 p-6 rounded-2xl animate-fade-in"
          style={{ 
            background: "var(--bg-card)", 
            border: "1px solid var(--border-default)",
            boxShadow: "var(--glow-amber)"
          }}
        >
          <div className="flex items-center gap-2 mb-6">
            <div className="p-1.5 rounded-lg bg-amber-400/10 text-amber-400">
              <Users size={16} />
            </div>
            <h2 className="font-display text-xl font-semibold">Generate Personas</h2>
          </div>
          <PersonaForm onGenerate={handleGenerate} loading={generating} />
        </div>
      )}

      {/* Filters & Search */}
      <div className="flex items-center gap-4 mb-8">
        <div className="flex-1 relative">
          <Search 
            size={16} 
            className="absolute left-4 top-1/2 -translate-y-1/2" 
            style={{ color: "var(--text-muted)" }}
          />
          <input 
            type="text"
            placeholder="Search personas by name, role, or trait..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && fetchPersonas()}
            className="w-full bg-transparent rounded-xl pl-11 pr-4 py-3 text-sm outline-none transition-all"
            style={{ 
              background: "var(--bg-card)", 
              border: "1px solid var(--border-subtle)" 
            }}
            onFocus={(e) => e.target.style.borderColor = "var(--border-default)"}
            onBlur={(e) => e.target.style.borderColor = "var(--border-subtle)"}
          />
        </div>
        <button 
          onClick={fetchPersonas}
          className="p-3 rounded-xl transition-all hover:bg-white/5"
          style={{ border: "1px solid var(--border-subtle)", color: "var(--text-secondary)" }}
        >
          <RotateCcw size={18} />
        </button>
        <button 
          className="flex items-center gap-2 px-4 py-3 rounded-xl text-sm transition-all hover:bg-white/5"
          style={{ border: "1px solid var(--border-subtle)", color: "var(--text-secondary)" }}
        >
          <Filter size={16} />
          Filter
        </button>
      </div>

      {/* Persona Grid */}
      {loading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-[280px] rounded-2xl shimmer opacity-50" />
          ))}
        </div>
      ) : personas.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {personas.map((persona) => (
            <PersonaCard 
              key={persona.id} 
              persona={persona} 
              onDelete={handleDelete}
            />
          ))}
        </div>
      ) : (
        <div 
          className="py-20 text-center rounded-2xl"
          style={{ background: "var(--bg-card)", border: "1px dashed var(--border-default)" }}
        >
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full mb-4 bg-white/5">
            <Users size={32} style={{ color: "var(--text-muted)" }} />
          </div>
          <h3 className="text-lg font-medium mb-1">No personas found</h3>
          <p className="text-sm mb-6" style={{ color: "var(--text-muted)" }}>
            Try adjusting your search or generate some new personas.
          </p>
          {!showForm && (
            <button 
              onClick={() => setShowForm(true)}
              className="text-sm font-semibold px-4 py-2 rounded-lg transition-colors"
              style={{ color: "var(--amber-400)", border: "1px solid var(--amber-400)" }}
            >
              Start Generating
            </button>
          )}
        </div>
      )}
    </div>
  );
}
